package main

const researchQuotaPoolHTML = `
<details id="research-quota-pools" class="research-schedules">
<summary>研究共用額度池</summary>
<p>為同一 Provider、帳戶或專案的多把 Key 設定共用研究次數、token 與 USD 上限。每個適用的池都必須有足夠預算，留空停用該項限制，0 停止新核准。</p>
<p>這是此引擎的本機研究政策，供應商官方剩餘額度及其他裝置耗用仍另計。加入成員會納入其今日既有研究用量；移除成員、停用或修改上限不會抹去已核准紀錄。每日 UTC 00:00（台灣 08:00）另起一天。</p>
<p id="research-pool-status" role="status">展開後讀取共用額度池。</p>
<div class="toolbar"><button id="research-pool-refresh" class="ghost" type="button">更新共用池用量</button><button id="research-pool-create" type="button" disabled>新增共用額度池</button><button id="research-pool-history" class="ghost" type="button">共用池變更紀錄</button></div>
<div id="research-pool-list" class="cards"></div><button id="research-pool-more" class="ghost" type="button" hidden>顯示更多共用池</button>
<p class="section-description">失敗、取消或缺少回報仍保留 token／USD 預留。預留額沿用上方研究預算；供應商可能超出預留。調整池或跨日後仍須明確恢復研究，日常聊天不扣此研究預算。</p>
</details>`

const jsResearchQuotaPools = `
let researchPoolState=null,researchPoolLoading=false,researchPoolWriting=false;
const researchPoolKinds={PROVIDER:'Provider',ACCOUNT:'帳戶',PROJECT:'專案',CUSTOM:'自選憑證'};
function setResearchPoolBusy(){const root=$('research-quota-pools'),busy=researchPoolLoading||researchPoolWriting;root.setAttribute('aria-busy',String(busy));root.querySelectorAll('button').forEach(b=>b.disabled=busy||b.id==='research-pool-create'&&!researchPoolState);}
async function loadResearchQuotaPools(more=false){
 if(researchPoolLoading||researchPoolWriting)return;researchPoolLoading=true;setResearchPoolBusy();
 try{const v=await api('/research/quota-pools'+(more&&researchPoolState?.next_after?'?after='+encodeURIComponent(researchPoolState.next_after):''));if(!Number.isInteger(v.revision)||!Array.isArray(v.pools))throw Error('無法辨識共用額度池。');if(more&&researchPoolState&&(v.revision!==researchPoolState.revision||v.day!==researchPoolState.day))throw Error('政策或日期已改變，請更新後重新讀取。');if(more&&researchPoolState)v.pools=[...researchPoolState.pools,...v.pools];researchPoolState=v;renderResearchQuotaPools();$('research-pool-status').textContent=v.day+' · 本機研究共用池，官方剩餘額度尚未量測。';return true;}
 catch(e){$('research-pool-status').textContent=(researchPoolState?'讀取失敗，保留上次共用池及編輯草稿。 ':'尚未取得共用池。 ')+e.message;return false;}finally{researchPoolLoading=false;setResearchPoolBusy();}
}
function poolScopeText(d){const provider=providers.find(p=>p.id===d.provider_id),account=accounts.find(a=>a.provider_id===d.provider_id&&a.id===d.account_id);return researchPoolKinds[d.kind]+' · '+(d.kind==='CUSTOM'?d.members.length+' 份指定憑證':(provider?.name||d.provider_id)+(d.account_id?' / '+(account?.label||d.account_id):'')+(d.project?' / '+d.project:''));}
function renderResearchQuotaPools(){const list=$('research-pool-list');list.replaceChildren();for(const row of researchPoolState.pools){const d=row.definition,card=item(list,d.label,(d.enabled?'啟用':'停用')+' · '+poolScopeText(d)+' · 今日核准 '+row.today_requests+' / '+resourceLimitText(d.requests)+' 次；上限 '+resourceLimitText(d.tokens)+' token／'+resourceLimitText(d.usd)+' USD。 '+resourceUsageText(row.usage)+(row.older_unbudgeted_requests?' 另有 '+row.older_unbudgeted_requests+' 筆舊請求未追溯 token／USD，啟用該項限制將停止新核准。':''));card.dataset.poolId=d.id;action(card,'編輯共用池',()=>editResearchQuotaPool(d,researchPoolState.revision));}if(!researchPoolState.pools.length)item(list,'尚無共用額度池','新增帳戶或專案共用上限。');$('research-pool-more').hidden=!researchPoolState.next_after;}
function editResearchQuotaPool(existing=null,revision=researchPoolState?.revision){
 if(!revision||researchPoolLoading||researchPoolWriting)return;
 const box=modal(existing?'編輯共用額度池':'新增共用額度池'),ticket=detailVersion,form=el('form'),problem=el('p'),read=el('button','重讀最新共用池'),reload=el('button','捨棄草稿並載入最新設定');read.type=reload.type='button';problem.setAttribute('role','status');
 const draft=existing||{id:crypto.randomUUID(),label:'',kind:'ACCOUNT',provider_id:providers[0]?.id||'',account_id:'',project:'',enabled:true,requests:null,tokens:null,usd:null,members:[]};
 box.append(el('p','每個適用共用池與全域／逐憑證限制會一起核對。加入成員納入今日既有研究用量；移除後保留本池已核准用量。Provider／帳戶會包含其之後新增的 Key；專案與自選憑證須逐份明確選擇。池的範圍建立後固定。'),form,problem,read,reload);
 form.className='research-pool-editor';
 const name=field(form,'共用池名稱','text',draft.label),kind=el('select'),kindLabel=el('label','共用範圍'),provider=el('select'),providerLabel=el('label','共用 Provider'),account=el('select'),accountLabel=el('label','共用帳戶');kind.setAttribute('aria-label','共用範圍');provider.setAttribute('aria-label','共用 Provider');account.setAttribute('aria-label','共用帳戶');for(const [value,label]of Object.entries(researchPoolKinds))option(kind,value,label);kind.value=draft.kind;kindLabel.append(kind);providerLabel.append(provider);accountLabel.append(account);form.append(kindLabel,providerLabel,accountLabel);name.required=true;name.maxLength=120;
 providers.forEach(p=>option(provider,p.id,p.name));if(draft.provider_id&&![...provider.options].some(n=>n.value===draft.provider_id))option(provider,draft.provider_id,draft.provider_id);provider.value=draft.provider_id;
 const project=field(form,'專案識別（自行確認）','text',draft.project),members=el('fieldset'),legend=el('legend','共用成員');members.append(legend);form.append(members);const chosen=new Map(draft.members.map(s=>[JSON.stringify([s.provider_id,s.account_id,s.credential_id]),s]));
 const renderScopes=()=>{const previous=account.value;account.replaceChildren();accounts.filter(a=>a.provider_id===provider.value).forEach(a=>option(account,a.id,a.label||a.id));if(draft.account_id&&existing&&![...account.options].some(n=>n.value===draft.account_id))option(account,draft.account_id,draft.account_id);account.value=previous||draft.account_id||account.options[0]?.value||'';members.replaceChildren(legend);const choices=new Map();for(const c of credentials.filter(c=>c.role==='INFERENCE')){const s={provider_id:c.provider_id,account_id:c.account_id,credential_id:c.id};choices.set(JSON.stringify([s.provider_id,s.account_id,s.credential_id]),{s,label:c.label||c.id});}for(const [key,s]of chosen)if(!choices.has(key))choices.set(key,{s,label:s.credential_id+'（歷史憑證）'});for(const [key,{s,label}]of choices){if(kind.value==='PROJECT'&&s.provider_id!==provider.value)continue;const wrap=el('label'),input=el('input');input.type='checkbox';input.checked=chosen.has(key);input.addEventListener('change',()=>{if(input.checked)chosen.set(key,s);else chosen.delete(key);});wrap.append(input,document.createTextNode(label+' · '+s.provider_id+' / '+s.account_id+' / '+s.credential_id));members.append(wrap);}providerLabel.hidden=kind.value==='CUSTOM';accountLabel.hidden=kind.value!=='ACCOUNT';project.parentElement.hidden=kind.value!=='PROJECT';members.hidden=!['PROJECT','CUSTOM'].includes(kind.value);};
 kind.addEventListener('change',renderScopes);provider.addEventListener('change',()=>{account.value='';renderScopes();});renderScopes();if(existing){kind.disabled=provider.disabled=account.disabled=project.disabled=true;}
 const requests=field(form,'共用每日推論上限','number',draft.requests===null?'':String(draft.requests)),tokens=field(form,'共用每日 token 上限','number',draft.tokens===null?'':String(draft.tokens)),usd=field(form,'共用每日 USD 上限','text',draft.usd===null?'':draft.usd);requests.min=tokens.min='0';requests.max='2000';tokens.max='1000000000000';requests.step=tokens.step='1';usd.inputMode='decimal';const enabled=el('input'),enabledLabel=el('label','啟用此共用池');enabledLabel.className='research-pool-enabled';enabled.type='checkbox';enabled.checked=draft.enabled;enabledLabel.append(enabled);form.append(enabledLabel,el('p','留空停用該項限制，0 停止核准。只修改本機研究政策，不會清除用量或自動恢復研究。'),el('button','保存共用額度池'));
 let saving=false;
 form.addEventListener('submit',async e=>{e.preventDefault();if(saving||researchPoolLoading||researchPoolWriting||ticket!==detailVersion)return;saving=researchPoolWriting=true;setResearchPoolBusy();form.querySelector('button').disabled=true;problem.textContent='';const k=kind.value,value={revision,id:draft.id,label:name.value.trim(),kind:k,provider_id:k==='CUSTOM'?'':provider.value,account_id:k==='ACCOUNT'?account.value:'',project:k==='PROJECT'?project.value.trim():'',enabled:enabled.checked,requests:resourceNullable(requests.value,true),tokens:resourceNullable(tokens.value,true),usd:resourceNullable(usd.value),members:['PROJECT','CUSTOM'].includes(k)?[...chosen.values()].filter(s=>k!=='PROJECT'||s.provider_id===provider.value):[]};let committed=false;try{await submit('/research/quota-pools',value);committed=true;notice('共用額度池已保存，用量與研究暫停狀態保留。');if(ticket===detailVersion)$('detail').close();}catch(error){if(ticket===detailVersion)problem.textContent=error.message+'；草稿保留，請重讀後明確選擇是否捨棄。';}finally{saving=researchPoolWriting=false;setResearchPoolBusy();form.querySelector('button').disabled=false;}if(committed)await loadResearchQuotaPools();});
 read.addEventListener('click',async()=>{if(saving)return;const fresh=await loadResearchQuotaPools();if(ticket===detailVersion)problem.textContent=fresh?'最新清單已重新讀取；草稿的原版本保留。':'讀取失敗，編輯草稿與原版本保留。';});reload.addEventListener('click',async()=>{if(saving)return;const fresh=await loadResearchQuotaPools();if(ticket!==detailVersion||!fresh||!researchPoolState)return;const current=existing?researchPoolState.pools.find(r=>r.definition.id===draft.id)?.definition:null;if(existing&&!current){problem.textContent='最新設定不在目前分頁，請關閉後從清單重新開啟。';return;}editResearchQuotaPool(current,researchPoolState.revision);});
}
async function researchQuotaPoolHistory(){const box=modal('共用池變更紀錄'),ticket=detailVersion,list=el('div'),problem=el('p'),more=el('button','讀取更多共用池變更');box.append(list,problem,more);let before=0,loading=false;const read=async()=>{if(loading)return;loading=true;more.disabled=true;try{const v=await api('/research/quota-pools?history=1'+(before?'&before='+before:''));if(ticket!==detailVersion)return;for(const row of v.history){const d=row.definition;item(list,'版本 '+row.revision+' · '+d.label+' · '+new Date(row.changed_at).toLocaleString(),(d.enabled?'啟用':'停用')+' · '+poolScopeText(d)+' · '+resourceLimitText(d.requests)+' 次／'+resourceLimitText(d.tokens)+' token／'+resourceLimitText(d.usd)+' USD');}before=v.next_before;more.hidden=!before;problem.textContent='';}catch(e){if(ticket===detailVersion)problem.textContent=e.message;}finally{loading=false;more.disabled=false;}};more.addEventListener('click',read);await read();}
function bindResearchQuotaPools(){$('research-quota-pools').addEventListener('toggle',()=>{if($('research-quota-pools').open)loadResearchQuotaPools();});document.addEventListener('visibilitychange',()=>{if(researchScheduleVisible()&&$('research-quota-pools').open)loadResearchQuotaPools();});$('research-pool-refresh').addEventListener('click',()=>loadResearchQuotaPools());$('research-pool-create').addEventListener('click',()=>editResearchQuotaPool());$('research-pool-more').addEventListener('click',()=>loadResearchQuotaPools(true));$('research-pool-history').addEventListener('click',researchQuotaPoolHistory);}
`

const researchQuotaPoolCSS = `
#research-quota-pools{min-width:0;overflow-wrap:anywhere}#research-pool-status{font-size:.85rem;color:var(--muted)}#research-pool-list .item{min-width:0;overflow-wrap:anywhere}.research-pool-editor fieldset{min-width:0;max-width:100%;border:1px solid var(--border);border-radius:10px;padding:12px}.research-pool-editor fieldset>label{display:flex;align-items:center;gap:10px;overflow-wrap:anywhere;min-height:48px}.research-pool-editor fieldset input[type=checkbox],.research-pool-enabled input{flex:none;width:20px;height:20px}.research-pool-enabled{display:flex;align-items:center;gap:12px;min-height:48px}
`
